import fs from "node:fs/promises";
import path from "node:path";
import type {
  Decision,
  Dependency,
  Domain,
  Endpoint,
  ExternalDependency,
  GraphNode,
  Network,
  Service,
  Snapshot,
  Volume,
  Warning,
} from "@infrajournal/core";
import type { GenerateDocumentationOptions, GenerateDocumentationResult } from "../types.js";
import { cell, code, codeCell, mermaidLabel, plural, sourceLabel, text } from "./escape.js";

export const GENERATED_MARKER =
  "<!-- Generated by InfraJournal. Manual edits will be overwritten. -->";

const PAGE_NAMES = [
  "README.md",
  "architecture.md",
  "services.md",
  "networks.md",
  "storage.md",
  "domains.md",
  "warnings.md",
  "decisions.md",
] as const;

export class DocumentationError extends Error {
  constructor(
    message: string,
    readonly detail?: string,
  ) {
    super(message);
    this.name = "DocumentationError";
  }
}

interface Heading {
  heading: string;
  anchor: string;
}

interface Anchors {
  services: Map<string, Heading>;
  networks: Map<string, Heading>;
  volumes: Map<string, Heading>;
  domains: Map<string, Heading>;
  decisions: Map<string, Heading>;
}

function githubSlug(value: string): string {
  return value
    .normalize("NFKD")
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/[\s]+/g, "-")
    .replace(/-+/g, "-");
}

function buildAnchors<T extends { id: string }>(
  items: T[],
  label: (item: T) => string,
  secondary: (item: T) => string,
): Map<string, Heading> {
  const result = new Map<string, Heading>();
  const used = new Set<string>();
  for (const item of items) {
    let heading = label(item);
    if (used.has(githubSlug(heading))) heading = `${heading} (${secondary(item)})`;
    let anchor = githubSlug(heading);
    let counter = 2;
    while (used.has(anchor)) {
      heading = `${label(item)} (${secondary(item)} ${counter})`;
      anchor = githubSlug(heading);
      counter += 1;
    }
    used.add(anchor);
    result.set(item.id, { heading, anchor });
  }
  return result;
}

function buildAnchorsFor(snapshot: Snapshot): Anchors {
  return {
    services: buildAnchors(
      snapshot.services,
      (item) => item.name,
      (item) => item.composeProject,
    ),
    networks: buildAnchors(
      snapshot.networks,
      (item) => item.name,
      (item) => item.composeProject ?? "network",
    ),
    volumes: buildAnchors(
      snapshot.volumes,
      (item) => item.name,
      (item) => item.composeProject ?? "volume",
    ),
    domains: buildAnchors(
      snapshot.domains,
      (item) => item.name,
      (item) => item.proxy,
    ),
    decisions: buildAnchors(
      snapshot.decisions,
      (item) => item.title,
      (item) => item.id,
    ),
  };
}

function link(page: string, heading: Heading | undefined, fallback: string): string {
  if (!heading) return code(fallback);
  return `[${text(heading.heading)}](${page}#${heading.anchor})`;
}

function countBy<T>(items: T[], key: (item: T) => string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    const value = key(item);
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  return new Map([...counts.entries()].sort(([a], [b]) => a.localeCompare(b)));
}

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KiB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MiB`;
}

function severityOrder(warning: Warning): number {
  return warning.severity === "ERROR" ? 0 : warning.severity === "WARNING" ? 1 : 2;
}

function renderPorts(service: Service): string {
  if (service.ports.length === 0) return "—";
  return service.ports
    .map((port) => {
      const published = port.published
        ? `${port.hostIp ? `${port.hostIp}:` : ""}${port.published} → `
        : "";
      return code(`${published}${port.target}/${port.protocol}`);
    })
    .join("<br />");
}

function renderNetworkNames(service: Service, snapshot: Snapshot): string {
  const names = new Map(snapshot.networks.map((network) => [network.id, network.name]));
  if (service.networkIds.length === 0) return "—";
  return service.networkIds.map((id) => code(names.get(id) ?? id)).join("<br />");
}

function header(title: string): string {
  return `${GENERATED_MARKER}\n\n# ${title}\n`;
}

function footer(snapshot: Snapshot): string {
  return `\n---\n\nGenerated by InfraJournal ${code(snapshot.metadata.generatorVersion)} from snapshot ${code(
    snapshot.metadata.contentHash.slice(0, 12),
  )}. Source locations are relative to the project root.\n`;
}

function pageOverview(snapshot: Snapshot): string {
  const warningCounts = {
    error: snapshot.warnings.filter((item) => item.severity === "ERROR").length,
    warning: snapshot.warnings.filter((item) => item.severity === "WARNING").length,
    info: snapshot.warnings.filter((item) => item.severity === "INFO").length,
  };

  const counts: Array<[string, number, string]> = [
    ["Services", snapshot.services.length, "services.md"],
    ["Networks", snapshot.networks.length, "networks.md"],
    ["Volumes", snapshot.volumes.length, "storage.md"],
    ["Domains", snapshot.domains.length, "domains.md"],
    ["Endpoints", snapshot.endpoints.length, "architecture.md#endpoints"],
    ["Dependencies", snapshot.dependencies.length, "architecture.md#dependencies"],
    ["Warnings", snapshot.warnings.length, "warnings.md"],
    ["Decisions", snapshot.decisions.length, "decisions.md"],
    ["Scanned files", snapshot.files.length, "#scanned-files"],
  ];

  const lines = [
    header(`${text(snapshot.project.name)} infrastructure`),
    `> Your infrastructure, automatically documented. This directory is generated from ${plural(
      snapshot.files.length,
      "configuration file",
    )} by [InfraJournal](https://github.com/infrajournal/infrajournal). It is read-only analysis: no Docker daemon, cloud service or AI provider was contacted.`,
    "",
    "## At a glance",
    "",
    "| Area | Count | Details |",
    "| --- | ---: | --- |",
    ...counts.map(([label, count, target]) => `| ${label} | ${count} | [Open](${target}) |`),
    "",
  ];

  if (snapshot.project.composeProjects.length > 0) {
    lines.push(
      `Docker Compose projects: ${snapshot.project.composeProjects.map((name) => code(name)).join(", ")}`,
      "",
    );
  }

  lines.push(
    "## Warnings",
    "",
    `**${warningCounts.error}** errors, **${warningCounts.warning}** warnings and **${warningCounts.info}** informational findings.`,
    "",
  );

  if (snapshot.warnings.length === 0) {
    lines.push("No warnings were produced for this snapshot.", "");
  } else {
    lines.push(
      "| Severity | Code | Message | Source |",
      "| --- | --- | --- | --- |",
      ...[...snapshot.warnings]
        .sort(
          (a, b) =>
            severityOrder(a) - severityOrder(b) ||
            a.code.localeCompare(b.code) ||
            a.message.localeCompare(b.message),
        )
        .slice(0, 10)
        .map(
          (warning) =>
            `| ${warning.severity} | ${codeCell(warning.code)} | ${cell(warning.message)} | ${codeCell(
              sourceLabel(warning.source),
            )} |`,
        ),
      "",
    );
    if (snapshot.warnings.length > 10) {
      lines.push(`[See all ${snapshot.warnings.length} warnings](warnings.md).`, "");
    }
  }

  lines.push(
    "## Documentation",
    "",
    "| Page | What it contains |",
    "| --- | --- |",
    "| [Architecture](architecture.md) | Dependency graph, evidence legend and graph statistics |",
    "| [Services](services.md) | Images, ports, mounts, networks, dependencies and environment key names |",
    "| [Networks](networks.md) | Network drivers, membership and external status |",
    "| [Storage](storage.md) | Named volumes, bind mounts and backup policies |",
    "| [Domains](domains.md) | Proxy sites, TLS state, routes and upstream resolution |",
    "| [Warnings](warnings.md) | Every diagnostic with severity and source |",
    "| [Decisions](decisions.md) | Architecture decision records linked to services |",
    "",
    "## Scanned files",
    "",
  );

  if (snapshot.files.length === 0) {
    lines.push("No supported configuration files were found.", "");
  } else {
    lines.push(
      "| File | Kind | Size |",
      "| --- | --- | ---: |",
      ...snapshot.files.map(
        (file) => `| ${codeCell(file.path)} | ${file.kind} | ${formatBytes(file.bytes)} |`,
      ),
      "",
    );
  }

  lines.push(
    "## Snapshot metadata",
    "",
    "| Field | Value |",
    "| --- | --- |",
    `| Project ID | ${codeCell(snapshot.project.id)} |`,
    `| Schema version | ${codeCell(snapshot.schemaVersion)} |`,
    `| Generator | ${codeCell(`${snapshot.metadata.generator} ${snapshot.metadata.generatorVersion}`)} |`,
    `| Generated at | ${codeCell(snapshot.metadata.generatedAt)} |`,
    `| Content hash | ${codeCell(snapshot.metadata.contentHash)} |`,
    "",
    "> Environment variable values, `env_file` contents and secret files are never read or stored. Only variable names and referenced paths are documented.",
    "",
    "The canonical machine-readable source is [`snapshot.json`](snapshot.json). See the [InfraJournal documentation](https://github.com/infrajournal/infrajournal) for configuration and limitations.",
    footer(snapshot),
  );

  return lines.join("\n");
}

const NODE_LIMIT = 120;
const EDGE_LIMIT = 240;

const NODE_PRIORITY: Record<GraphNode["kind"], number> = {
  domain: 0,
  service: 1,
  network: 2,
  volume: 3,
  endpoint: 4,
  external: 5,
};

function mermaidDiagram(snapshot: Snapshot): { diagram: string; truncated: boolean } {
  const sorted = [...snapshot.graphNodes].sort(
    (a, b) => NODE_PRIORITY[a.kind] - NODE_PRIORITY[b.kind] || a.id.localeCompare(b.id),
  );
  const selected = sorted.slice(0, NODE_LIMIT);
  const nodeIds = new Map(selected.map((node, index) => [node.id, `n${index}`]));
  const truncatedNodes = sorted.length > selected.length;

  const edges = [...snapshot.dependencies].sort(
    (a, b) =>
      a.type.localeCompare(b.type) || a.from.localeCompare(b.from) || a.to.localeCompare(b.to),
  );
  const renderable = edges.filter((edge) => nodeIds.has(edge.from) && nodeIds.has(edge.to));
  const selectedEdges = renderable.slice(0, EDGE_LIMIT);
  const truncatedEdges = renderable.length > selectedEdges.length;

  const lines = ["flowchart LR"];
  for (const node of selected) {
    const id = nodeIds.get(node.id);
    if (!id) continue;
    const sublabel = node.sublabel ? `<br/>${mermaidLabel(node.sublabel)}` : "";
    lines.push(`  ${id}["${mermaidLabel(node.label)}${sublabel}"]`);
  }

  for (const edge of selectedEdges) {
    const from = nodeIds.get(edge.from);
    const to = nodeIds.get(edge.to);
    if (!from || !to) continue;
    const arrow = edge.evidence.kind === "inferred" ? "-.->" : "-->";
    const label = edge.evidence.kind === "inferred" ? `${edge.type} (inferred)` : edge.type;
    lines.push(`  ${from} ${arrow}|${label}| ${to}`);
  }

  const style: Record<GraphNode["kind"], string> = {
    service: "fill:#083344,stroke:#22d3ee,color:#ecfeff",
    network: "fill:#1e1b4b,stroke:#818cf8,color:#eef2ff",
    volume: "fill:#3f2d12,stroke:#fbbf24,color:#fffbeb",
    domain: "fill:#052e2b,stroke:#34d399,color:#ecfdf5",
    endpoint: "fill:#3b1d2b,stroke:#f472b6,color:#fdf2f8",
    external: "fill:#27272a,stroke:#a1a1aa,color:#fafafa",
  };
  for (const kind of Object.keys(style) as GraphNode["kind"][]) {
    lines.push(`  classDef ${kind} ${style[kind]}`);
  }
  for (const node of selected) {
    const id = nodeIds.get(node.id);
    if (id) lines.push(`  class ${id} ${node.kind}`);
  }

  return {
    diagram: lines.join("\n"),
    truncated: truncatedNodes || truncatedEdges,
  };
}

function pageArchitecture(snapshot: Snapshot): string {
  const diagram = mermaidDiagram(snapshot);
  const kindCounts = countBy(snapshot.graphNodes, (node) => node.kind);
  const dependencyCounts = countBy(snapshot.dependencies, (edge) => edge.type);
  const evidenceCounts = countBy(snapshot.dependencies, (edge) => edge.evidence.kind);

  const lines = [
    header("Architecture"),
    "The graph is derived only from the scanned configuration subset. Solid edges are explicit or implicit facts from configuration; dashed edges are conservative inferences based on service names, image families and shared networks.",
    "",
    "```mermaid",
    diagram.diagram,
    "```",
    "",
  ];

  if (diagram.truncated) {
    lines.push(
      `> The diagram is truncated to keep it readable. See ${code("snapshot.json")} for the complete graph (${snapshot.graphNodes.length} nodes, ${snapshot.dependencies.length} edges).`,
      "",
    );
  }

  lines.push(
    "## Legend",
    "",
    "| Visual | Meaning |",
    "| --- | --- |",
    "| Solid arrow | Explicit `depends_on`, an explicit route, or an implicit structural edge |",
    "| Dashed arrow | Inferred edge; verify before relying on it |",
    "| Cyan | Service |",
    "| Indigo | Network |",
    "| Amber | Volume |",
    "| Emerald | Domain |",
    "| Pink | Endpoint |",
    "| Grey | External dependency |",
    "",
    "## Nodes",
    "",
    "| Kind | Count |",
    "| --- | ---: |",
    ...["service", "network", "volume", "domain", "endpoint", "external"].map(
      (kind) => `| ${kind} | ${kindCounts.get(kind) ?? 0} |`,
    ),
    "",
    "## Dependencies",
    "",
  );

  if (snapshot.dependencies.length === 0) {
    lines.push("No dependency edges were derived.", "");
  } else {
    lines.push(
      "| Edge type | Count |",
      "| --- | ---: |",
      ...[...dependencyCounts.entries()].map(([type, count]) => `| ${type} | ${count} |`),
      "",
      "| Evidence | Count |",
      "| --- | ---: |",
      ...[...evidenceCounts.entries()].map(([kind, count]) => `| ${kind} | ${count} |`),
      "",
    );
  }

  lines.push("## Endpoints", "");
  if (snapshot.endpoints.length === 0) {
    lines.push("No published endpoints were derived.", "");
  } else {
    const services = new Map(snapshot.services.map((service) => [service.id, service.name]));
    lines.push(
      "| Endpoint | Transport | Port | Published | Service | Source |",
      "| --- | --- | --- | --- | --- | --- |",
      ...snapshot.endpoints.map(
        (endpoint: Endpoint) =>
          `| ${codeCell(endpoint.name)} | ${endpoint.transport} | ${codeCell(endpoint.port ?? "—")} | ${codeCell(
            endpoint.published ?? "—",
          )} | ${codeCell(services.get(endpoint.serviceId ?? "") ?? "—")} | ${codeCell(
            sourceLabel(endpoint.source),
          )} |`,
      ),
      "",
    );
  }

  lines.push("## External dependencies", "");
  if (snapshot.external.length === 0) {
    lines.push("No external upstreams or files were referenced.", "");
  } else {
    lines.push(
      "| Name | Category | Detail | Source |",
      "| --- | --- | --- | --- |",
      ...snapshot.external.map(
        (item: ExternalDependency) =>
          `| ${codeCell(item.name)} | ${item.category} | ${codeCell(item.detail ?? "—")} | ${codeCell(
            sourceLabel(item.source),
          )} |`,
      ),
      "",
    );
  }

  lines.push("## Dependency list", "");
  if (snapshot.dependencies.length === 0) {
    lines.push("No dependency edges were derived.", "");
  } else {
    const labels = new Map(snapshot.graphNodes.map((node) => [node.id, node.label]));
    lines.push(
      "| From | Type | To | Evidence | Reason |",
      "| --- | --- | --- | --- | --- |",
      ...snapshot.dependencies.map((edge: Dependency) => {
        const reason = edge.evidence.reason ? cell(edge.evidence.reason) : "—";
        return `| ${codeCell(labels.get(edge.from) ?? edge.from)} | ${edge.type} | ${codeCell(
          labels.get(edge.to) ?? edge.to,
        )} | ${edge.evidence.kind} | ${reason} |`;
      }),
      "",
    );
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function renderRelatedWarnings(warnings: Warning[]): string[] {
  if (warnings.length === 0) return ["- None", ""];
  return [
    ...warnings.map(
      (warning) =>
        `- **${warning.severity}** ${code(warning.code)} — ${text(warning.message)}${
          warning.suggestion ? ` _Suggestion:_ ${text(warning.suggestion)}` : ""
        }`,
    ),
    "",
  ];
}

function pageServices(snapshot: Snapshot, anchors: Anchors): string {
  const warningsByResource = new Map<string, Warning[]>();
  for (const warning of snapshot.warnings) {
    for (const related of warning.related) {
      const list = warningsByResource.get(related) ?? [];
      list.push(warning);
      warningsByResource.set(related, list);
    }
  }

  const labels = new Map(snapshot.graphNodes.map((node) => [node.id, node.label]));
  const lines = [
    header("Services"),
    `${plural(snapshot.services.length, "service")} across ${plural(
      snapshot.project.composeProjects.length,
      "Compose project",
    )}. Environment values are never read; only key names are listed.`,
    "",
  ];

  if (snapshot.services.length === 0) {
    lines.push("No services were discovered.", footer(snapshot));
    return lines.join("\n");
  }

  lines.push(
    "| Service | Image or build | Ports | Networks | Explicit dependencies | Source |",
    "| --- | --- | --- | --- | --- | --- |",
    ...snapshot.services.map((service) => {
      const build = service.build
        ? `build ${service.build.context}${service.build.dockerfile ? ` (${service.build.dockerfile})` : ""}`
        : "—";
      return `| ${link("services.md", anchors.services.get(service.id), service.name)} | ${codeCell(
        service.image ?? build,
      )} | ${renderPorts(service)} | ${renderNetworkNames(service, snapshot)} | ${codeCell(
        service.dependsOn
          .map((id) => snapshot.services.find((candidate) => candidate.id === id)?.name ?? id)
          .join(", ") || "—",
      )} | ${codeCell(sourceLabel(service.source))} |`;
    }),
    "",
  );

  for (const service of snapshot.services) {
    const heading = anchors.services.get(service.id);
    const outgoing = snapshot.dependencies.filter((edge) => edge.from === service.id);
    const incoming = snapshot.dependencies.filter((edge) => edge.to === service.id);
    const warnings = warningsByResource.get(service.id) ?? [];

    lines.push(
      `## ${text(heading?.heading ?? service.name)}`,
      "",
      `- **ID:** ${code(service.id)}`,
      `- **Compose project:** ${code(service.composeProject)}`,
      `- **Source:** ${code(sourceLabel(service.source))}`,
      `- **Image:** ${service.image ? code(service.image) : "—"}`,
      `- **Build:** ${
        service.build
          ? `${code(service.build.context)}${service.build.dockerfile ? ` (${code(service.build.dockerfile)})` : ""}`
          : "—"
      }`,
      `- **Restart policy:** ${service.restart ? code(service.restart) : "—"}`,
      `- **Healthcheck:** ${service.healthcheck ? "declared" : "not declared"}`,
      "",
      "### Ports",
      "",
    );

    if (service.ports.length === 0) {
      lines.push("No ports are published or exposed.", "");
    } else {
      lines.push(
        "| Host IP | Published | Container | Protocol |",
        "| --- | --- | --- | --- |",
        ...service.ports.map(
          (port) =>
            `| ${codeCell(port.hostIp ?? "—")} | ${codeCell(port.published ?? "—")} | ${codeCell(
              port.target,
            )} | ${port.protocol} |`,
        ),
        "",
      );
    }

    lines.push("### Networks", "");
    if (service.networkIds.length === 0) {
      lines.push("No explicit network membership.", "");
    } else {
      for (const id of service.networkIds) {
        const network = snapshot.networks.find((item) => item.id === id);
        lines.push(
          `- ${network ? link("networks.md", anchors.networks.get(id), network.name) : code(id)}`,
        );
      }
      lines.push("");
    }

    lines.push("### Mounts", "");
    if (service.mounts.length === 0) {
      lines.push("No volume or bind mounts.", "");
    } else {
      lines.push(
        "| Type | Source | Target | Read-only |",
        "| --- | --- | --- | --- |",
        ...service.mounts.map((mount) => {
          let source = mount.source ?? "—";
          if (mount.type === "named" && mount.volumeId) {
            const volume = snapshot.volumes.find((item) => item.id === mount.volumeId);
            if (volume) {
              const volumeHeading = anchors.volumes.get(volume.id);
              source = volumeHeading
                ? `[${text(volumeHeading.heading)}](storage.md#${volumeHeading.anchor})`
                : volume.name;
            }
          } else if (mount.source) {
            source = code(mount.source);
          }
          return `| ${mount.type} | ${source} | ${codeCell(mount.target)} | ${
            mount.readOnly ? "yes" : "no"
          } |`;
        }),
        "",
      );
    }

    lines.push("### Dependencies", "");
    if (outgoing.length === 0 && incoming.length === 0) {
      lines.push("No dependency edges reference this service.", "");
    } else {
      if (service.dependsOn.length > 0) {
        lines.push("Explicit `depends_on`:", "");
        for (const id of service.dependsOn) {
          const target = snapshot.services.find((item) => item.id === id);
          lines.push(
            `- ${
              target ? link("services.md", anchors.services.get(id), target.name) : code(id)
            } (explicit)`,
          );
        }
        lines.push("");
      }
      if (outgoing.length > 0) {
        lines.push("Outgoing edges:", "");
        for (const edge of outgoing) {
          lines.push(
            `- ${edge.type} → ${code(labels.get(edge.to) ?? edge.to)} (${edge.evidence.kind})`,
          );
        }
        lines.push("");
      }
      if (incoming.length > 0) {
        lines.push("Incoming edges:", "");
        for (const edge of incoming) {
          lines.push(
            `- ${edge.type} ← ${code(labels.get(edge.from) ?? edge.from)} (${edge.evidence.kind})`,
          );
        }
        lines.push("");
      }
    }

    lines.push("### Configuration keys", "");
    lines.push(
      `- Environment keys: ${
        service.environmentKeys.length > 0
          ? service.environmentKeys.map((key) => code(key)).join(", ")
          : "none"
      }`,
      `- Referenced env files: ${
        service.envFiles.length > 0 ? service.envFiles.map((file) => code(file)).join(", ") : "none"
      } (contents are not read)`,
      `- Label keys: ${
        service.labelKeys.length > 0 ? service.labelKeys.map((key) => code(key)).join(", ") : "none"
      }`,
      "",
      "### Warnings",
      "",
      ...renderRelatedWarnings(warnings),
    );
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function pageNetworks(snapshot: Snapshot, anchors: Anchors): string {
  const lines = [
    header("Networks"),
    `${plural(snapshot.networks.length, "network")} declared or implicitly created by the scanned Compose files.`,
    "",
  ];

  if (snapshot.networks.length === 0) {
    lines.push("No networks were discovered.", footer(snapshot));
    return lines.join("\n");
  }

  const servicesByNetwork = new Map<string, Service[]>();
  for (const service of snapshot.services) {
    for (const networkId of service.networkIds) {
      const list = servicesByNetwork.get(networkId) ?? [];
      list.push(service);
      servicesByNetwork.set(networkId, list);
    }
  }

  lines.push(
    "| Network | Driver | External | Implicit | Services | Source |",
    "| --- | --- | --- | --- | ---: | --- |",
    ...snapshot.networks.map((network: Network) => {
      const members = servicesByNetwork.get(network.id) ?? [];
      return `| ${link("networks.md", anchors.networks.get(network.id), network.name)} | ${codeCell(
        network.driver ?? "—",
      )} | ${network.external ? "yes" : "no"} | ${network.implicit ? "yes" : "no"} | ${
        members.length
      } | ${codeCell(sourceLabel(network.source))} |`;
    }),
    "",
  );

  for (const network of snapshot.networks) {
    const heading = anchors.networks.get(network.id);
    const members = servicesByNetwork.get(network.id) ?? [];
    lines.push(
      `## ${text(heading?.heading ?? network.name)}`,
      "",
      `- **ID:** ${code(network.id)}`,
      `- **Driver:** ${network.driver ? code(network.driver) : "—"}`,
      `- **External:** ${network.external ? "yes" : "no"}`,
      `- **Implicitly created:** ${network.implicit ? "yes" : "no"}`,
      `- **Source:** ${code(sourceLabel(network.source))}`,
      `- **Evidence:** ${network.evidence.kind}${network.evidence.reason ? ` — ${text(network.evidence.reason)}` : ""}`,
      "",
      "### Attached services",
      "",
    );
    if (members.length === 0) {
      lines.push("No scanned service attaches to this network.", "");
    } else {
      for (const service of members) {
        lines.push(
          `- ${link("services.md", anchors.services.get(service.id), service.name)} (${code(service.id)})`,
        );
      }
      lines.push("");
    }
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function pageStorage(snapshot: Snapshot, anchors: Anchors): string {
  const lines = [
    header("Storage"),
    `${plural(snapshot.volumes.length, "named volume")} and all declared mounts. A missing backup policy means the policy is not documented in configuration; it does not mean backups do not exist.`,
    "",
  ];

  if (snapshot.volumes.length === 0) {
    lines.push("No named volumes were discovered.", "");
  } else {
    lines.push(
      "| Volume | Driver | External | Backup policy | Source |",
      "| --- | --- | --- | --- | --- |",
      ...snapshot.volumes.map((volume: Volume) => {
        const backup = volume.backup
          ? `${text(volume.backup.policy)} _(${volume.backup.source})_`
          : "not documented";
        return `| ${link("storage.md", anchors.volumes.get(volume.id), volume.name)} | ${codeCell(
          volume.driver ?? "—",
        )} | ${volume.external ? "yes" : "no"} | ${backup} | ${codeCell(
          sourceLabel(volume.source),
        )} |`;
      }),
      "",
    );

    const mountsByVolume = new Map<
      string,
      Array<{ service: Service; target: string; readOnly: boolean }>
    >();
    for (const service of snapshot.services) {
      for (const mount of service.mounts) {
        if (!mount.volumeId) continue;
        const list = mountsByVolume.get(mount.volumeId) ?? [];
        list.push({ service, target: mount.target, readOnly: mount.readOnly });
        mountsByVolume.set(mount.volumeId, list);
      }
    }

    for (const volume of snapshot.volumes) {
      const heading = anchors.volumes.get(volume.id);
      const mounts = mountsByVolume.get(volume.id) ?? [];
      lines.push(
        `## ${text(heading?.heading ?? volume.name)}`,
        "",
        `- **ID:** ${code(volume.id)}`,
        `- **Backup policy:** ${volume.backup ? text(volume.backup.policy) : "not documented"}`,
        `- **Policy source:** ${volume.backup ? volume.backup.source : "—"}`,
        `- **Source:** ${code(sourceLabel(volume.source))}`,
        "",
        "### Mounted by",
        "",
      );
      if (mounts.length === 0) {
        lines.push("Not mounted by any scanned service.", "");
      } else {
        lines.push(
          "| Service | Container path | Read-only |",
          "| --- | --- | --- |",
          ...mounts.map(
            (mount) =>
              `| ${link("services.md", anchors.services.get(mount.service.id), mount.service.name)} | ${codeCell(
                mount.target,
              )} | ${mount.readOnly ? "yes" : "no"} |`,
          ),
          "",
        );
      }
    }
  }

  const bindMounts = snapshot.services.flatMap((service) =>
    service.mounts.filter((mount) => mount.type !== "named").map((mount) => ({ service, mount })),
  );

  lines.push("## Bind and anonymous mounts", "");
  if (bindMounts.length === 0) {
    lines.push("No bind or anonymous mounts were discovered.", "");
  } else {
    lines.push(
      "| Service | Type | Host source | Container path | Read-only |",
      "| --- | --- | --- | --- | --- |",
      ...bindMounts.map(
        ({ service, mount }) =>
          `| ${link("services.md", anchors.services.get(service.id), service.name)} | ${mount.type} | ${codeCell(
            mount.source ?? "—",
          )} | ${codeCell(mount.target)} | ${mount.readOnly ? "yes" : "no"} |`,
      ),
      "",
    );
    lines.push(
      "> Bind mount sources are documented as written in configuration. InfraJournal does not read their contents.",
      "",
    );
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function pageDomains(snapshot: Snapshot, anchors: Anchors): string {
  const lines = [
    header("Domains"),
    `${plural(snapshot.domains.length, "domain")} declared by the supported Nginx and Caddy subsets.`,
    "",
  ];

  if (snapshot.domains.length === 0) {
    lines.push("No domains were discovered.", footer(snapshot));
    return lines.join("\n");
  }

  lines.push(
    "| Domain | Proxy | TLS | Routes | Source |",
    "| --- | --- | --- | ---: | --- |",
    ...snapshot.domains.map(
      (domain: Domain) =>
        `| ${link("domains.md", anchors.domains.get(domain.id), domain.name)} | ${domain.proxy} | ${
          domain.tls ? "yes" : "no"
        } | ${domain.routes.length} | ${codeCell(sourceLabel(domain.source))} |`,
    ),
    "",
  );

  for (const domain of snapshot.domains) {
    const heading = anchors.domains.get(domain.id);
    lines.push(
      `## ${text(heading?.heading ?? domain.name)}`,
      "",
      `- **ID:** ${code(domain.id)}`,
      `- **Proxy:** ${domain.proxy}`,
      `- **TLS:** ${domain.tls ? "enabled or terminated" : "not declared"}`,
      `- **Source:** ${code(sourceLabel(domain.source))}`,
      `- **Evidence:** ${domain.evidence.kind}${domain.evidence.reason ? ` — ${text(domain.evidence.reason)}` : ""}`,
      "",
      "### Routes",
      "",
    );
    if (domain.routes.length === 0) {
      lines.push("No routes were parsed for this domain.", "");
    } else {
      lines.push(
        "| Path | Upstream | Resolved service | Source |",
        "| --- | --- | --- | --- |",
        ...domain.routes.map((route) => {
          const service = route.serviceId
            ? snapshot.services.find((item) => item.id === route.serviceId)
            : undefined;
          const resolved = service
            ? link("services.md", anchors.services.get(service.id), service.name)
            : route.externalId
              ? code(route.externalId)
              : "unresolved";
          return `| ${codeCell(route.path ?? "/")} | ${codeCell(route.upstream)} | ${resolved} | ${codeCell(
            sourceLabel(route.source),
          )} |`;
        }),
        "",
      );
    }
  }

  if (snapshot.external.length > 0) {
    lines.push(
      "## External upstreams",
      "",
      "| Name | Category | Detail | Source |",
      "| --- | --- | --- | --- |",
      ...snapshot.external.map(
        (item) =>
          `| ${codeCell(item.name)} | ${item.category} | ${codeCell(item.detail ?? "—")} | ${codeCell(
            sourceLabel(item.source),
          )} |`,
      ),
      "",
    );
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function pageWarnings(snapshot: Snapshot, anchors: Anchors): string {
  const lines = [
    header("Warnings"),
    `${plural(snapshot.warnings.length, "diagnostic")} produced while scanning. Warnings describe parser limits and possible configuration problems; they are not a security audit.`,
    "",
  ];

  if (snapshot.warnings.length === 0) {
    lines.push("No warnings were produced.", footer(snapshot));
    return lines.join("\n");
  }

  const bySeverity = countBy(snapshot.warnings, (warning) => warning.severity);
  const byCode = countBy(snapshot.warnings, (warning) => warning.code);
  lines.push(
    "## Summary",
    "",
    "| Severity | Count |",
    "| --- | ---: |",
    ...["ERROR", "WARNING", "INFO"].map(
      (severity) => `| ${severity} | ${bySeverity.get(severity) ?? 0} |`,
    ),
    "",
    "| Code | Count |",
    "| --- | ---: |",
    ...[...byCode.entries()].map(([codeValue, count]) => `| ${codeCell(codeValue)} | ${count} |`),
    "",
  );

  const resourceLabel = (id: string): string => {
    const service = snapshot.services.find((item) => item.id === id);
    if (service) return link("services.md", anchors.services.get(id), service.name);
    const network = snapshot.networks.find((item) => item.id === id);
    if (network) return link("networks.md", anchors.networks.get(id), network.name);
    const volume = snapshot.volumes.find((item) => item.id === id);
    if (volume) return link("storage.md", anchors.volumes.get(id), volume.name);
    const domain = snapshot.domains.find((item) => item.id === id);
    if (domain) return link("domains.md", anchors.domains.get(id), domain.name);
    return code(id);
  };

  for (const severity of ["ERROR", "WARNING", "INFO"] as const) {
    const warnings = snapshot.warnings
      .filter((warning) => warning.severity === severity)
      .sort((a, b) => a.code.localeCompare(b.code) || a.message.localeCompare(b.message));
    if (warnings.length === 0) continue;

    lines.push(`## ${severity}`, "");
    for (const warning of warnings) {
      lines.push(
        `### ${code(warning.code)}`,
        "",
        text(warning.message),
        "",
        `- **ID:** ${code(warning.id)}`,
        `- **Source:** ${code(sourceLabel(warning.source))}`,
        `- **Related:** ${
          warning.related.length > 0 ? warning.related.map(resourceLabel).join(", ") : "—"
        }`,
      );
      if (warning.suggestion) lines.push(`- **Suggestion:** ${text(warning.suggestion)}`);
      lines.push("");
    }
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function pageDecisions(snapshot: Snapshot, anchors: Anchors): string {
  const lines = [
    header("Decisions"),
    `${plural(snapshot.decisions.length, "architecture decision record")} loaded from the configured decisions directory.`,
    "",
  ];

  if (snapshot.decisions.length === 0) {
    lines.push(
      "No decision records were found. Add YAML files to the configured `decisions.directory` to document why the infrastructure looks the way it does.",
      "",
      footer(snapshot),
    );
    return lines.join("\n");
  }

  lines.push(
    "| Decision | Status | Date | Related services |",
    "| --- | --- | --- | --- |",
    ...snapshot.decisions.map((decision: Decision) => {
      const related = decision.relatedServices
        .map((id) => {
          const service = snapshot.services.find((item) => item.id === id);
          return service ? link("services.md", anchors.services.get(id), service.name) : code(id);
        })
        .join(", ");
      return `| ${link("decisions.md", anchors.decisions.get(decision.id), decision.title)} | ${
        decision.status
      } | ${decision.date} | ${related || "—"} |`;
    }),
    "",
  );

  for (const decision of snapshot.decisions) {
    const heading = anchors.decisions.get(decision.id);
    lines.push(
      `## ${text(heading?.heading ?? decision.title)}`,
      "",
      `**Status:** ${decision.status} · **Date:** ${decision.date}`,
      "",
      `- **ID:** ${code(decision.id)}`,
      `- **Source:** ${code(sourceLabel(decision.source))}`,
      "",
      "### Context",
      "",
      text(decision.context),
      "",
      "### Decision",
      "",
      text(decision.decision),
      "",
      "### Consequences",
      "",
    );
    if (decision.consequences.length === 0) {
      lines.push("None recorded.", "");
    } else {
      for (const consequence of decision.consequences) {
        lines.push(`- ${text(consequence)}`);
      }
      lines.push("");
    }

    lines.push("### Related services", "");
    if (decision.relatedServices.length === 0 && decision.unresolvedRelatedServices.length === 0) {
      lines.push("None recorded.", "");
    } else {
      for (const id of decision.relatedServices) {
        const service = snapshot.services.find((item) => item.id === id);
        lines.push(
          `- ${service ? link("services.md", anchors.services.get(id), service.name) : code(id)}`,
        );
      }
      for (const name of decision.unresolvedRelatedServices) {
        lines.push(`- ${code(name)} — unresolved; no matching scanned service`);
      }
      lines.push("");
    }
  }

  lines.push(footer(snapshot));
  return lines.join("\n");
}

function renderPages(snapshot: Snapshot, anchors: Anchors): Map<string, string> {
  return new Map<string, string>([
    ["README.md", pageOverview(snapshot)],
    ["architecture.md", pageArchitecture(snapshot)],
    ["services.md", pageServices(snapshot, anchors)],
    ["networks.md", pageNetworks(snapshot, anchors)],
    ["storage.md", pageStorage(snapshot, anchors)],
    ["domains.md", pageDomains(snapshot, anchors)],
    ["warnings.md", pageWarnings(snapshot, anchors)],
    ["decisions.md", pageDecisions(snapshot, anchors)],
  ]);
}

async function isGeneratedFile(target: string): Promise<boolean> {
  let stat;
  try {
    stat = await fs.stat(target);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return true;
    throw error;
  }
  if (!stat.isFile()) {
    throw new DocumentationError(
      `Cannot write generated documentation because the target exists and is not a file: ${target}`,
    );
  }
  const existing = await fs.readFile(target, "utf8");
  return existing.split(/\r?\n/, 3).some((line) => line.trim() === GENERATED_MARKER);
}

async function atomicWrite(target: string, content: string): Promise<void> {
  const temporary = `${target}.tmp-${process.pid}-${Math.random().toString(16).slice(2)}`;
  try {
    await fs.writeFile(temporary, content, { encoding: "utf8", mode: 0o600 });
    await fs.rename(temporary, target);
  } catch (error) {
    await fs.rm(temporary, { force: true }).catch(() => undefined);
    throw error;
  }
}

export async function generateDocumentation(
  options: GenerateDocumentationOptions,
): Promise<GenerateDocumentationResult> {
  const outputDirectory = path.resolve(options.outputDirectory);
  const anchors = buildAnchorsFor(options.snapshot);
  const pages = renderPages(options.snapshot, anchors);

  await fs.mkdir(outputDirectory, { recursive: true });

  const written: string[] = [];
  const preserved: string[] = [];

  for (const name of PAGE_NAMES) {
    const content = pages.get(name);
    if (content === undefined) continue;
    const target = path.join(outputDirectory, name);
    if (!(await isGeneratedFile(target))) {
      preserved.push(name);
      continue;
    }
    await atomicWrite(target, content);
    written.push(name);
  }

  return { written, preserved };
}
